row(14, 1, 'MATERIAL', f'YOU ARE CHILDREN OF THE LORD YOUR GOD; YOU SHALL NOT CUT YOURSELVES NOR MAKE A BALDNESS BETWEEN YOUR EYES FOR THE DEAD. {HP(14, 1, (("בנים", "אתם", "ליהוה", "אלהיכם"), "you are children of the LORD your God — ONE seat in the Bible"), (("לא", "תתגדדו"), "you shall not cut yourselves — the Torah\'s one seat of the root"), (("קרחה", "בין", "עיניכם", "למת"), "a baldness between your eyes for the dead — the frontlets\' phrase at its fifth seat"))} {AP(14, 1, (("בנין", "אתון", "קדם", "יי"), "children you are BEFORE the LORD — the English\'s bracket the Aramaic\'s word"), (("לא", "תתחממון"), "you shall not make incisions — the Aramaic\'s own root, not the Hebrew\'s"), (("על", "מית"), "for a dead one"))} THE OPENING: the sonship (96:9\'s two arms), the cutting read twice (96:10-11), the baldness by analogy (96:12).')
row(14, 2, 'MATERIAL', f'FOR YOU ARE A HOLY PEOPLE TO THE LORD YOUR GOD, AND THE LORD HAS CHOSEN YOU TO BE HIS TREASURED PEOPLE FROM ALL THE PEOPLES ON THE FACE OF THE EARTH. {HP(14, 2, (("כי", "עם", "קדוש", "אתה", "ליהוה", "אלהיך"), "for a holy people you are to the LORD your God — 7:6\'s clause, three seats in the Bible"), (("ובך", "בחר", "יהוה", "להיות", "לו", "לעם", "סגלה"), "and you the LORD has chosen to be His treasured people — 7:6 with the second your God dropped"))} {AP(14, 2, (("לעם", "חביב"), "a BELOVED people — treasure rendered beloved at its four seats"), (("מכל", "עממיא", "די", "על", "אפי", "ארעא"), "from all the peoples on the face of the earth"))} THE REASON CLAUSE: 97:1\'s command and cause; 97:4-5\'s each one beloved, not above the fathers; 312:1\'s who chose.')
row(14, 3, 'MATERIAL', f'YOU SHALL NOT EAT ANY ABOMINATION. {HP(14, 3, (("לא", "תאכל", "כל", "תועבה"), "you shall not eat any abomination — the chapter\'s one of the book\'s seventeen"))} {AP(14, 3, (("לא", "תיכול", "כל", "דמרחק"), "you shall not eat anything REMOVED — abomination rendered what is far, at eleven seats"))} THE FOUR-WORD VERSE: the maimed firstling (99:1), the disqualified consecrated by analogy with 17:1 (99:2).')
row(14, 4, 'MATERIAL', f'THIS IS THE BEAST WHICH YOU SHALL EAT: THE OX, THE SHEEP OF THE LAMBS AND THE SHEEP OF THE GOATS. {HP(14, 4, (("זאת", "הבהמה", "אשר", "תאכלו"), "this is the beast which you shall eat — the list\'s header, Leviticus 11:2\'s twin"), (("שור", "שה", "כשבים", "ושה", "עזים"), "the ox, the sheep, the goat — the three domestic"))} {AP(14, 4, (("דין", "בעירא", "דתיכלון"), "this is the beast you shall eat"), (("תורין", "אמרין", "דרחלין", "וגדין", "דעזין"), "oxen, lambs of the ewes and kids of the goats — the plurals"))} THE THREE DOMESTIC: 100:1-2\'s two headers read into each other; 101\'s license by the names.')
row(14, 5, 'MATERIAL', f'THE HART, THE GAZELLE, THE ROEBUCK, THE WILD GOAT, THE PYGARG, THE ANTELOPE AND THE MOUNTAIN-SHEEP. {HP(14, 5, (("איל", "וצבי", "ויחמור"), "the hart, the gazelle, the roebuck — Solomon\'s table the one kin"), (("ואקו", "ודישן", "ותאו", "וזמר"), "the wild goat, the pygarg, the antelope, the mountain-sheep — three hapax and a Horite\'s name"))} {AP(14, 5, (("אילא", "וטביא", "ויחמורא"), "the hart, the gazelle, the roebuck"), (("ויעלא", "ורימא", "ותורבלא", "ודיצא"), "the ya\'ala, the rema, the turbala, the ditsa — names, not glosses"))} THE SEVEN WILD, NAMED HERE AND NOT IN LEVITICUS 11: 100:3\'s antelope the wild ox; the exam identifies the rest (Chullin 80a).')
row(14, 6, 'MATERIAL', f'AND EVERY BEAST THAT PARTS THE HOOF AND CLEAVES THE CLEFT INTO TWO HOOFS, CHEWING THE CUD AMONG THE BEASTS — IT YOU SHALL EAT. {HP(14, 6, (("מפרסת", "פרסה", "ושסעת", "שסע", "שתי", "פרסות"), "parts the hoof and cleaves the cleft into TWO hoofs — the number the parser reads, ONE seat"), (("מעלת", "גרה", "בבהמה", "אתה", "תאכלו"), "chewing the cud among the beasts, it you shall eat — Leviticus 11:3\'s clause"))} {AP(14, 6, (("דסדיקא", "פרסתא", "ומטלפא", "טלפין", "תרתין", "פרסתא"), "that parts the hoof and cleaves cloven hoofs, two hoofs — the two carried"), (("מסקא", "פשרא"), "brings up the cud"))} THE TWO SIGNS: 98:1\'s three from the three clauses; 101:5-9\'s "among the beasts" and "it" — the offspring, the afterbirth, the whole born.')
row(14, 7, 'MATERIAL', f'BUT THIS YOU SHALL NOT EAT OF THOSE THAT CHEW THE CUD OR PART THE CLEFT HOOF — THE CLEFT ONE: THE CAMEL, THE HARE AND THE ROCK-BADGER, FOR THEY CHEW THE CUD BUT PART NOT THE HOOF; UNCLEAN THEY ARE TO YOU. {HP(14, 7, (("ממעלי", "הגרה", "וממפריסי", "הפרסה", "השסועה"), "of the chewers of the cud and the parters of the cleft hoof — the CLEFT ONE, one seat in the Bible"), (("את", "הגמל", "ואת", "הארנבת", "ואת", "השפן"), "the camel, the hare and the rock-badger — Leviticus 11:4-6\'s three in one verse"), (("טמאים", "הם", "לכם"), "unclean they are to you"))} {AP(14, 7, (("ית", "גמלא", "וית", "ארנבא", "וית", "טפזא"), "the camel, the hare and the tafza"), (("מסאבין", "אנון", "לכון"), "unclean they are to you"))} THE THREE CHEWERS: 98:2\'s creature, 102:1\'s "was Moses a hunter", 101:10\'s four from Scripture and the rest by a fortiori.')
row(14, 8, 'MATERIAL', f'AND THE SWINE, FOR IT PARTS THE HOOF BUT NOT THE CUD — UNCLEAN IT IS TO YOU; OF THEIR FLESH YOU SHALL NOT EAT AND THEIR CARCASS YOU SHALL NOT TOUCH. {HP(14, 8, (("ואת", "החזיר", "כי", "מפריס", "פרסה", "הוא"), "and the swine, for it parts the hoof — the Torah\'s two seats of the swine"), (("מבשרם", "לא", "תאכלו", "ובנבלתם", "לא", "תגעו"), "of their flesh you shall not eat and their carcass you shall not touch — Leviticus 11:8 verbatim"))} {AP(14, 8, (("וית", "חזירא"), "and the swine"), (("ובנבלתהון", "לא", "תקרבון"), "and their carcass you shall not DRAW NEAR to — the English\'s bracket"))} THE ONE PARTER: the carcass\'s touch the twin chapter\'s clause (101:9-10 the prohibition\'s seat).')
row(14, 9, 'MATERIAL', f'THIS YOU SHALL EAT OF ALL THAT IS IN THE WATERS: ALL THAT HAS FINS AND SCALES YOU SHALL EAT. {HP(14, 9, (("את", "זה", "תאכלו", "מכל", "אשר", "במים"), "this you shall eat of all that is in the waters"), (("כל", "אשר", "לו", "סנפיר", "וקשקשת", "תאכלו"), "all that has fins and scales you shall eat — Leviticus 11:9\'s twelve tokens in order"))} {AP(14, 9, (("ציצין", "וקלפין"), "fins and scales — the Aramaic\'s own pair"))} THE WATER: the two signs without the seas and the rivers of Leviticus 11:9 (asserted).')
row(14, 10, 'CONTEXT', f'AND ALL THAT HAS NOT FINS AND SCALES YOU SHALL NOT EAT — UNCLEAN IT IS TO YOU. {HP(14, 10, (("וכל", "אשר", "אין", "לו", "סנפיר", "וקשקשת"), "and all that has not fins and scales"), (("טמא", "הוא", "לכם"), "unclean it is to you — this chapter\'s word where Leviticus 11:10-12 says detestable"))} {AP(14, 10, (("מסאב", "הוא", "לכון"), "unclean it is to you"))} The negative arm.')
row(14, 11, 'MATERIAL', f'EVERY CLEAN BIRD YOU MAY EAT. {HP(14, 11, (("כל", "צפור", "טהרה", "תאכלו"), "every clean BIRD you may eat — the list\'s first frame, ONE seat"))} {AP(14, 11, (("כל", "צפר", "דכיא", "תיכלון"), "every clean bird you may eat"))} THE FIRST FRAME: 98:3\'s lexicon (bird = clean), 103:1-2\'s leper\'s bird, 228:5\'s paradigm at the nest.')
row(14, 12, 'MATERIAL', f'AND THIS IS WHAT YOU SHALL NOT EAT OF THEM: THE EAGLE, THE OSSIFRAGE AND THE OSPREY. {HP(14, 12, (("וזה", "אשר", "לא", "תאכלו", "מהם"), "and this is what you shall not eat of them — the prohibition\'s header, Leviticus 11:13\'s detest made not eat"), (("הנשר", "והפרס", "והעזניה"), "the eagle, the ossifrage, the osprey"))} {AP(14, 12, (("נשרא", "וער", "ועזיא"), "the eagle, the ar and the aziya"))} THE SECOND HEADER: 103:3\'s eagle the analogy\'s word (two prohibitions on each name); 103:8\'s signs built from the eagle.')
row(14, 13, 'MATERIAL', f'AND THE RA\'AH AND THE AYYAH AND THE DAYYAH AFTER ITS KIND. {HP(14, 13, (("והראה", "ואת", "האיה", "והדיה", "למינה"), "and the ra\'ah and the ayyah and the dayyah after its kind — three names against Leviticus 11:14\'s two; resh for dalet"))} {AP(14, 13, (("ובת", "כנפא", "וטרפיתא", "ודיתא", "לזנה"), "and the daughter of the wing, the tarfita and the dita after its kind"))} THE LETTER THAT DIFFERS: 98:5-6\'s one bird by its kinds and the reason the chapter is restated; 103:4\'s analogy on the ayyah.')
row(14, 14, 'CONTEXT', f'AND EVERY RAVEN AFTER ITS KIND. {HP(14, 14, (("ואת", "כל", "ערב", "למינו"), "and every raven after its kind — Leviticus 11:15 with the vav"))} {AP(14, 14, (("וית", "כל", "ערבא", "לזניה"), "and every raven after its kind"))} 103:5\'s kinds.')
row(14, 15, 'CONTEXT', f'AND THE OSTRICH AND THE NIGHT-HAWK AND THE SEA-MEW AND THE HAWK AFTER ITS KIND. {HP(14, 15, (("ואת", "בת", "היענה", "ואת", "התחמס"), "and the ostrich and the night-hawk"), (("ואת", "השחף", "ואת", "הנץ", "למינהו"), "and the sea-mew and the hawk after its kind — 14:15 is Leviticus 11:16 to the letter"))} {AP(14, 15, (("וית", "בת", "נעמיתא"), "and the daughter of the ostrich"))} 103:6\'s hawk and its kind.')
row(14, 16, 'CONTEXT', f'THE LITTLE OWL AND THE GREAT OWL AND THE HORNED OWL. {HP(14, 16, (("את", "הכוס", "ואת", "הינשוף", "והתנשמת"), "the little owl, the great owl and the horned owl — the shalach moved, the tinshemet moved from Leviticus 11:17-18"))} {AP(14, 16, (("וקדיא", "וקפופא", "ובותא"), "the kadya, the kefufa and the buta"))} The order differs from the twin (asserted).')
row(14, 17, 'CONTEXT', f'AND THE PELICAN AND THE CARRION-VULTURE AND THE CORMORANT. {HP(14, 17, (("והקאת", "ואת", "הרחמה", "ואת", "השלך"), "and the pelican and the racham — spelled rachamah — and the cormorant"))} {AP(14, 17, (("וקתא", "וירקרקא", "ושלי", "נונא"), "the kata, the yerakraka and the fish-drawer"))} 103:7\'s count rule — the fewer named.')
row(14, 18, 'CONTEXT', f'AND THE STORK AND THE HERON AFTER ITS KIND AND THE HOOPOE AND THE BAT. {HP(14, 18, (("והחסידה", "והאנפה", "למינה", "והדוכיפת", "והעטלף"), "and the stork and the heron after its kind and the hoopoe and the bat — Leviticus 11:19 without the object-markers"))} {AP(14, 18, (("וחוריתא", "ואבו", "לזנה"), "the white one and the abu after its kind"), (("ונגר", "טורא", "ועטלפא"), "the mountain-carpenter and the bat"))} The list\'s end.')
row(14, 19, 'MATERIAL', f'AND EVERY SWARMING THING OF THE FOWL IS UNCLEAN TO YOU; THEY SHALL NOT BE EATEN. {HP(14, 19, (("וכל", "שרץ", "העוף", "טמא", "הוא", "לכם"), "and every swarming thing of the fowl is unclean to you"), (("לא", "יאכלו"), "they shall not be eaten — the chapter\'s one third-person form"))} {AP(14, 19, (("וכל", "רחשא", "דעופא"), "and every creeping thing of the fowl"), (("לא", "יתאכלון"), "they shall not be eaten"))} THE SWARMING FOWL: 103:10\'s prohibition and R. Shimon\'s unclean locusts — Leviticus 11:21-22\'s permitted four not in this chapter (asserted).')
row(14, 20, 'MATERIAL', f'EVERY CLEAN FOWL YOU MAY EAT. {HP(14, 20, (("כל", "עוף", "טהור", "תאכלו"), "every clean FOWL you may eat — the list\'s second frame, ONE seat"))} {AP(14, 20, (("כל", "עופא", "דכי", "תיכלון"), "every clean fowl you may eat"))} THE SECOND FRAME: 103:9\'s positive command, R. Shimon\'s clean locusts (103:10); 98:4\'s two nouns.')
